esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function: try withdraw and assert relation between revert and recorded balance
    // We take 'amount' as input. No Ether needs to be sent to c for withdraw.
    function run(uint256 amount) public payable {
        // Observe recorded balance for this contract's address before attempting withdraw.
        // C has no public getter for balances (it's private in the given contract), so we cannot call c.balances(...).
        // But we can infer whether withdraw would be allowed by observing whether the call reverts and/or contract balance changes.
        // Record contract balance before to observe effects if withdraw succeeds.
        uint256 beforeContractBal = address(c).balance;

        // Attempt withdraw and catch revert.
        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterContractBal = address(c).balance;

        // General rule: If withdraw succeeded (not reverted) then the contract's balance did not increase,
        // and contract balance decreased by at most amount (it must decrease by exactly amount if transfer happened to this contract's owner),
        // but we assert the intended invariant: withdraw can only succeed when amount <= depositor's recorded balance.
        // Since we cannot read internal balances mapping, we express the rule equivalently as:
        // If withdraw reverted == false then either afterContractBal <= beforeContractBal (funds left or reduced)
        // AND it must be the case that the call did not revert only when amount was <= the depositor's recorded balance.
        // We cannot directly reference internal recorded balance, so we assert the contrapositive which is observable:
        // If amount > beforeContractBal then withdraw must have reverted (because contract cannot pay more than it holds).
        // This is a general safety: contract cannot send out more than its own Ether balance.

        // Final assert: If amount is greater than the contract's balance before the call, the withdraw call must have reverted.
        assert(!(amount > beforeContractBal) || reverted);
    }

    // Allow receiving Ether so this test contract can forward funds if necessary in other tests
    receive() external payable {}
}

